## Code Example
```javascript
// Pseudo Step Functions failover workflow
const failoverWorkflow = {
  StartAt: 'CheckHealthStatus',
  States: {
    CheckHealthStatus: {
      Type: 'Task',
      Resource: 'arn:aws:lambda:region:account:function:health-check',
      Next: 'EvaluateFailoverDecision'
    },
    EvaluateFailoverDecision: {
      Type: 'Choice',
      Choices: [{
        Variable: '$.healthy',
        BooleanEquals: false,
        Next: 'InitiateFailover'
      }],
      Default: 'EndWorkflow'
    },
    InitiateFailover: {
      Type: 'Parallel',
      Branches: [
        { StartAt: 'PromoteRDSReplica' },
        { StartAt: 'UpdateDNSRecords' },
        { StartAt: 'NotifyStakeholders' }
      ],
      Next: 'ValidateFailover'
    }
  }
};
```
